head.script:
scwin.gVar = {
    "cUserData1" : ""
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = function () {
    // 기존 target(alias) 삭제 후 원본 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof dma_org !== 'undefined') {
        $p.data.remove("dma_org");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // 조건 설정       
    let properties = {
        userData1: scwin.gVar["cUserData1"],
    };

    let cList = $c.gcm.createCList(properties);       

    // alias 원본 dataMap 생성
    $c.gcm.createBasicDataMap('', '', 'dma_org');

    // target 생성 (aliasDataMap : scope 속성에 원본 dataMap ID 지정)
    let strTarget = '<w2:aliasDataMap ' + $c.gcm.getNameSpace() + ' ' + cList + ' id="target1" scope="dma_org"></w2:aliasDataMap>';
    $p.data.create(strTarget);

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');
}
